python3 -I -c '
import json,sys,collections
d=json.load(open(sys.argv[1])); e=json.loads(d[0]["text"])[0]["e"]
nodes=set(x for p in e for x in p); out=collections.defaultdict(list)
for a,b in e: out[a].append(b)
s={n:(1.0 if n=="Paddington" else 0.0) for n in nodes}; s0=dict(s)
for it in range(20):
  new={n:(0.15 if n=="Paddington" else 0.0) for n in nodes}
  for a in nodes:
    for b in out[a]: new[b]+=0.85*s[a]/len(out[a])
  s=new
print(s["Royal Oak"],s["Paddington"],len(nodes))
