  sourceNodeProperties: {zone: toFloat(n.zone)}, targetNodeProperties: {zone: toFloat(m.zone)},
  relationshipType: type(r), relationshipProperties: {distance: toFloat(r.distance)}
}, {undirectedRelationshipTypes: ['LINK']})

