order=["Aldgate","Tower Hill","Monument","Cannon Street","Mansion House","Aldgate East","Whitechapel","Shoreditch","Stepney Green","Shadwell","Liverpool Street","Bethnal Green","Mile End","Stratford","Bow Road","Moorgate","Barbican","Farringdon","Old Street","Angel","Bank","Waterloo","Southwark","Westminster","Lambeth North","Kennington","Embankment","St. Paul's","Chancery Lane","London Bridge","Bermondsey","Borough"]
E="""Liverpool Street|Aldgate;Tower Hill|Aldgate;Liverpool Street|Aldgate East;Tower Hill|Aldgate East;Whitechapel|Aldgate East;Old Street|Angel;Liverpool Street|Bank;London Bridge|Bank;Moorgate|Bank;Shadwell|Bank;St. Paul's|Bank;Waterloo|Bank;Farringdon|Barbican;Moorgate|Barbican;London Bridge|Bermondsey;Liverpool Street|Bethnal Green;Mile End|Bethnal Green;London Bridge|Borough;Mile End|Bow Road;Mansion House|Cannon Street;Monument|Cannon Street;St. Paul's|Chancery Lane;Waterloo|Embankment;Westminster|Embankment;Waterloo|Kennington;Waterloo|Lambeth North;Stepney Green|Mile End;Stratford|Mile End;Tower Hill|Monument;Old Street|Moorgate;Whitechapel|Shadwell;Whitechapel|Shoreditch;London Bridge|Southwark;Waterloo|Southwark;Westminster|Waterloo;Whitechapel|Stepney Green;Liverpool Street|Moorgate"""
adj={n:set() for n in order}
for p in E.split(";"):
    a,b=p.split("|"); adj[a].add(b); adj[b].add(a)
idx={n:i for i,n in enumerate(order)}
par={}
for n in order[1:]:
    par[n]=min((m for m in adj[n] if idx[m]<idx[n]),key=idx.get)
def path(n):
    p=[n]
    while p[-1] in par: p.append(par[p[-1]])
    return p[::-1]
leaves=[n for n in order if n not in par.values()]
for l in leaves: print(len(path(l))-1, path(l))
# check: DFS order consistent (each node's parent is on the current stack path)
