MAX=4;src=303
d={src:0};par={};pushed={src}
# visited-at-push, only push if depth+1<=MAX; parent = first expander that reaches node
for n in order:
    assert n in pushed, name[n]
    if d[n]<MAX:
        for t in adj[n]:
            if t not in pushed: pushed.add(t); par[t]=n; d[t]=d[n]+1
print("visited set equals pushed set:", set(order)==pushed)
# check DFS preorder consistency: each node's parent must be on the current root path
stack=[]
