python3 -c "
import json,sys
d=json.load(open(sys.argv[1]));e=json.loads(d[0]['text'])[0]['e']
nodes=set(x for p in e for x in p)
out={n:[] for n in nodes}
for a,b in e: out[a].append(b)
src='Paddington';pr={n:(1.0 if n==src else 0.0) for n in nodes}
for _ in range(20):
  new={n:(0.15 if n==src else 0.0) for n in nodes}
  for a in nodes:
    if out[a]:
      s=0.85*pr[a]/len(out[a])
      for b in out[a]: new[b]+=s
  pr=new
print(pr['Royal Oak'],pr['Paddington'])
