cd /tmp && python3 -I - <<'EOF'
import json,math
d=json.load(open('/Users/sbr/.claude/projects/-Users-sbr-gds-agent-benchmarks/0b6796b4-579d-424c-8800-7ca9ea1412de/tool-results/toolu_017xCWFdZoWHZia5DkaYEicZ.json'))
e=json.loads(d[0]['text'])[0]['e']
names=sorted({x for p in e for x in p}); N=len(names)
def run(it,tol=1e-7):
    x={n:1/N for n in names}
    for k in range(it):
        y={n:0.0 for n in names}
        for a,b in e: y[b]+=x[a]
        nr=math.sqrt(sum(v*v for v in y.values())); y={n:v/nr for n,v in y.items()}
        diff=sum(abs(y[n]-x[n]) for n in names); x=y
        if diff<tol: break
    return x['Canada Water'],k+1
print(N, run(20), run(100000,1e-12))
EOF

cd /tmp && python3 -I - <<'EOF'
import json,math
d=json.load(open('/Users/sbr/.claude/projects/-Users-sbr-gds-agent-benchmarks/0b6796b4-579d-424c-8800-7ca9ea1412de/tool-results/toolu_017xCWFdZoWHZia5DkaYEicZ.json'))
e=json.loads(d[0]['text'])[0]['e']
names=sorted({x for p in e for x in p}); N=len(names)
def run(it,selfloop,init,tol=1e-7):
    x={n:init for n in names}
    for k in range(it):
        y={n:(x[n] if selfloop else 0.0) for n in names}
        for a,b in e: y[b]+=x[a]
        nr=math.sqrt(sum(v*v for v in y.values())); y={n:v/nr for n,v in y.items()}
        conv=all(abs(y[n]-x[n])<tol for n in names); x=y
        if conv: break
    return x['Canada Water'],k+1
for s in (0,1):
  for init in (1/N,1.0):
    print(s,init,run(20,s,init),run(100000,s,init,1e-12))
EOF

