parameters.query:
MATCH (s:UndergroundStation {name:'Canary Wharf'})
MATCH (t:UndergroundStation) WHERE NOT EXISTS { MATCH (s)-[:LINK*0..]->(t) }
RETURN t.name ORDER BY t.name

